TLM.f("Sancti/01-28t",{"officium":"S. Agnetis Virginis et Martyris secundo","rule":["vide C6b;"],"ruleInherited":["Prefatio=Virginis"],"fallback":"Commune/C6b","from":{"Lectio":"Commune/C6b","Graduale":"Commune/C6b","GradualeP":"Commune/C6b","Tractus":"Commune/C6b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 44:13; 44:15; 44:16"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducántur Regi Vírgines post eam: próximæ ejus adducántur tibi in lætítia et exsultatióne."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducántur Regi Vírgines post eam: próximæ ejus adducántur tibi in lætítia et exsultatióne."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua beátæ Agnetis Vírginis et Martyris tuæ sollemnitáte lætíficas: da, quǽsumus; ut, quam venerámur officio, étiam piæ conversatiónis sequámur exémplo."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 10:17-18; 11:1-2"},{"k":"text","la":"Fratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo."}],"Graduale":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","la":"Ps 44:13; 44:10"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: fíliæ regum in honóre tuo."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."},{"k":"text","la":"Afferéntur in lætítia et exsultatióne: adducéntur in templum Regis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Super has, quǽsumus, Dómine, hóstias benedíctio copiósa descéndat: quæ et sanctificatiónem nobis cleménter operétur, et de Mártyrum nos sollemnitáte lætíficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 13:45-46"},{"k":"text","la":"Símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas: invénta autem una pretiósa margaríta, dedit ómnia sua, et comparávit eam."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, celebritátis ánnuæ votiva sacraménta: præsta, quǽsumus; ut et temporális vitæ nobis remédia prǽbeant et ætérnæ."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4fd4ad8dd1785c94":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom blažene Agneze tvoje djevice i mučenice, daj, molimo, da nju koju častimo službom također nasljedujemo uzornim pobožnim životom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nas svake godine razveseljuješ svetkovinom blažene Agneze, djevice i mučenice Tvoje, podaj, molimo, da pobožnim životom slijedimo primjer one, koje spomen slavimo. Po G n.","knRef":"Kniewald 1942, str. 494–495 (snimka 248) (OCR)"},"94a3bbb8ba9f5aa0":{"t":"Neka obilni blagoslov, molimo, Gospodine, siđe na ovaj prinos, da nas milostivo posveti i razveseli o svetkovini mučenika.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nad ove žrtve sade obilati blagoslov, koji neka nas posveti i razveseli 0 svetkovini mučemikai Tvojih, po G. n.","knRef":"Kniewald 1942, str. 494–495 (snimka 248) (OCR)"},"150f57ef8d5d33a5":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, zavjetna otajstva godišnje svečanosti, molimo te, da nam udijele okrepu i za vremeniti i za vječni život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, zavjetna otajstva godišnje svetkovine, molimo Te, da nam ndijele okrepo i za vremeniti i za vječni život, po G. n.","knRef":"Kniewald 1942, str. 702–703 (snimka 352) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}]}}});
